-- 1. Total Revenue generated by store
SELECT SUM(total) AS total_revenue
FROM Invoice;

-- 2. Revenue Breakdown by Country
SELECT 
    BillingCountry, 
    SUM(total) AS revenue,
    ROUND(100.0 * SUM(total) / (SELECT SUM(total) FROM Invoice), 2) AS pct_total_revenue
FROM Invoice
GROUP BY BillingCountry
ORDER BY revenue DESC;

-- 3. Top 10 Customers by Total Spending
SELECT 
    c.CustomerId, 
    c.FirstName || ' ' || c.LastName AS customer_name,
    c.Country,
    SUM(i.total) AS total_spent
FROM Customer c
JOIN Invoice i ON c.CustomerId = i.CustomerId
GROUP BY c.CustomerId, customer_name, c.Country
ORDER BY total_spent DESC
LIMIT 10;

-- 4. Top Revenue-Generating Artists
SELECT 
    ar.Name AS artist_name,
    SUM(il.UnitPrice * il.Quantity) AS total_revenue
FROM Artist ar
JOIN Album al ON ar.ArtistId = al.ArtistId
JOIN Track t ON al.AlbumId = t.AlbumId
JOIN InvoiceLine il ON t.TrackId = il.TrackId
GROUP BY ar.ArtistId, ar.Name
ORDER BY total_revenue DESC
LIMIT 10;

-- 5. Most Popular Music Genres by Purchases
SELECT 
    g.Name AS genre,
    COUNT(il.InvoiceLineId) AS total_purchases,
    SUM(il.UnitPrice * il.Quantity) AS genre_revenue
FROM Genre g
JOIN Track t ON g.GenreId = t.GenreId
JOIN InvoiceLine il ON t.TrackId = il.TrackId
GROUP BY g.GenreId, g.Name
ORDER BY total_purchases DESC;

-- 6. Average Spending per Customer
SELECT ROUND(AVG(customer_total), 2) AS avg_customer_spend
FROM (
    SELECT SUM(total) AS customer_total
    FROM Invoice
    GROUP BY CustomerId
) sub;

-- 7. Monthly Revenue Trend
SELECT 
    STRFTIME('%Y-%m', InvoiceDate) AS month,
    SUM(total) AS monthly_revenue
FROM Invoice
GROUP BY month
ORDER BY month;